 "content": "def transform(grid):
    """Stamp the 8-shaped marker onto every translated all-zero match."""
    h, w = len(grid), len(grid[0])
    marker = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 8]
    if not marker:
        return [row[:] for row in grid]
    r0 = min(r for r, c in marker)
    c0 = min(c for r, c in marker)
    shape = [(r-r0, c-c0) for r, c in marker]
    mh = max(r for r, c in shape) + 1
    mw = max(c for r, c in shape) + 1
    out = [row[:] for row in grid]
    for dr in range(h - mh + 1):
        for dc in range(w - mw + 1):
            if all(grid[dr+r][dc+c] == 0 for r, c in shape):
                for r, c in shape:
                    out[dr+r][dc+c] = 8
    return out
